/* vmactions.org -- enhancement only.
 *
 * Nothing here may be required to read or navigate the site. With JavaScript
 * disabled every page is still a complete document in the default language and
 * the system theme: the coverage matrix, the system cards and the hero's run
 * list are all real markup, generated by tools/build-data.js.
 *
 * What this file adds: the theme and language switches, copy buttons, the
 * hero's run animation, and the docs sidebar scroll-spy.
 */

(function () {
  'use strict';

  var root = document.documentElement;

  /* ---------------------------------------------------------- language */

  function currentLang() {
    return root.getAttribute('data-lang') === 'zh' ? 'zh' : 'en';
  }

  function setLang(lang) {
    root.setAttribute('data-lang', lang);
    root.setAttribute('lang', lang);
    try { localStorage.setItem('vma-lang', lang); } catch (e) {}
    paintThemeLabel();
  }

  var langSwitch = document.getElementById('lang-switch');
  if (langSwitch) {
    langSwitch.addEventListener('click', function () {
      setLang(currentLang() === 'zh' ? 'en' : 'zh');
    });
  }

  /* ------------------------------------------------------------- theme */

  var THEME_LABEL = {
    en: { light: 'Dark', dark: 'Light' },
    zh: { light: '深色', dark: '浅色' }
  };

  function currentTheme() {
    var set = root.getAttribute('data-theme');
    if (set === 'light' || set === 'dark') return set;
    return window.matchMedia &&
      window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }

  /* The button offers the theme you would switch TO. */
  function paintThemeLabel() {
    var label = document.querySelector('[data-theme-label]');
    if (label) label.textContent = THEME_LABEL[currentLang()][currentTheme()];
  }

  var themeSwitch = document.getElementById('theme-switch');
  if (themeSwitch) {
    themeSwitch.addEventListener('click', function () {
      var next = currentTheme() === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      try { localStorage.setItem('vma-theme', next); } catch (e) {}
      paintThemeLabel();
    });
  }

  paintThemeLabel();

  /* -------------------------------------------------------------- copy */

  var COPIED = { en: 'Copied', zh: '已复制' };

  Array.prototype.forEach.call(document.querySelectorAll('[data-copy]'), function (btn) {
    var target = document.querySelector(btn.getAttribute('data-copy'));
    if (!target || !navigator.clipboard) return;

    btn.addEventListener('click', function () {
      navigator.clipboard.writeText(target.textContent.trim()).then(function () {
        var keep = btn.innerHTML;
        btn.textContent = COPIED[currentLang()];
        setTimeout(function () { btn.innerHTML = keep; }, 1400);
      }, function () { /* clipboard refused; leave the button alone */ });
    });
  });

  /* --------------------------------------------------------- run list */

  var reduceMotion = window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  var runList = document.getElementById('run-list');
  if (runList && !reduceMotion) {
    var rows = Array.prototype.slice.call(runList.children);
    if (rows.length) {
      var at = 0;
      rows.forEach(function (row) { row.classList.add('pending'); });

      setInterval(function () {
        if (at >= rows.length) {
          rows.forEach(function (row) { row.classList.add('pending'); });
          at = 0;
          return;
        }
        rows[at].classList.remove('pending');
        at++;
      }, 420);
    }
  }

  /* ------------------------------------------------------- scroll-spy */

  var toc = document.querySelector('.toc');
  if (toc && window.IntersectionObserver) {
    var links = {};
    Array.prototype.forEach.call(toc.querySelectorAll('a[href^="#"]'), function (a) {
      links[a.getAttribute('href').slice(1)] = a;
    });

    var targets = Object.keys(links)
      .map(function (id) { return document.getElementById(id); })
      .filter(Boolean);

    if (targets.length) {
      var seen = {};
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) { seen[entry.target.id] = entry.isIntersecting; });

        var active = null;
        targets.forEach(function (t) { if (!active && seen[t.id]) active = t.id; });

        Object.keys(links).forEach(function (id) {
          links[id].classList.toggle('on', id === active);
        });
      }, { rootMargin: '-76px 0px -70% 0px' });

      targets.forEach(function (t) { observer.observe(t); });
    }
  }
})();
